```mermaid
flowchart TD
    Start([Start HTTP Request]) --> CB_Check{Circuit Breaker<br/>State?}
    CB_Check -->|Open| FailFast[Fail Fast: Circuit Open]
    CB_Check -->|Half-Open| Attempt[Attempt Request]
    CB_Check -->|Closed| Attempt

    Attempt --> Result{Request<br/>Succeeded?}
    Result -->|Yes| Success[Return Success]
    Result -->|No| IncAttempt[Increment Attempt Count]

    IncAttempt --> MaxCheck{Attempt <br/>>= 5?}
    MaxCheck -->|Yes| OpenCB[Open Circuit Breaker]
    OpenCB --> FailMax[Return Failure: Max Attempts]

    MaxCheck -->|No| CalcBackoff[Calculate Backoff:<br/>base * 2^attempt + jitter]
    CalcBackoff --> Wait[Wait Backoff Duration]
    Wait --> CB_Check

    Success --> CB_Success{Circuit Breaker<br/>Half-Open?}
    CB_Success -->|Yes| CloseCB[Close Circuit Breaker]
    CB_Success -->|No| ResetCount[Reset Attempt Count]
    CloseCB --> ResetCount
    ResetCount --> End([End])

    FailFast --> End
    FailMax --> End

    classDef decision fill:#f9f,stroke:#333,stroke-width:2px;
    classDef action fill:#bbf,stroke:#333,stroke-width:2px;
    classDef terminal fill:#fb4,stroke:#333,stroke-width:2px;

    class CB_Check,Result,MaxCheck,CB_Success decision;
    class Attempt,IncAttempt,CalcBackoff,Wait,OpenCB,CloseCB,ResetCount action;
    class Start,Success,FailFast,FailMax,End terminal;
```

