```dsl
sequence
participant Client [person]
participant "Our API" as API
participant Stripe [icon: tabler/brand-stripe]
participant "Stripe Webhook" as Webhook

Client -> API : POST /payments (amount, currency)
API -> Stripe : Create PaymentIntent
Stripe --> API : PaymentIntent { client_secret }
API --> Client : { client_secret, publishable_key }
Client -> Stripe : confirmCardPayment(client_secret)
alt payment succeeds {
  Stripe -> Webhook : payment_intent.succeeded
  Webhook -> API : POST /webhooks/stripe
  API --> Webhook : 200 OK
  Stripe --> Client : redirect to success_url
  Client -> API : GET /payments/:id/status
  API --> Client : { status: "succeeded" }
} else payment fails {
  Stripe --> Client : error
  Client -> API : GET /payments/:id/status
  API --> Client : { status: "failed" }
}
note over Webhook, API : Webhook may arrive\nbefore client redirect
```

```dsl
sequence
participant User [person]
participant Frontend [browser]
participant AuthAPI [component]
participant DB [db]
participant TOTP [component]

User -> Frontend : enters username + password
Frontend -> AuthAPI : POST /login {username, password}
AuthAPI -> DB : find user by username
DB --> AuthAPI : user record (with TOTP secret)
alt invalid credentials {
  AuthAPI --> Frontend : 401 Invalid credentials
  Frontend --> User : show error
} else valid {
  AuthAPI --> Frontend : 200 {requireTotp: true, challengeId}
  Frontend --> User : prompt for TOTP code

  loop up to 3 attempts {
    User -> Frontend : enters TOTP code
    Frontend -> AuthAPI : POST /login/totp {challengeId, code}
    AuthAPI -> TOTP : verify(code, secret)
    alt code valid {
      TOTP --> AuthAPI : valid
      AuthAPI --> Frontend : 200 {token, refreshToken}
      Frontend --> User : redirect to app
      break
    } else code invalid {
      TOTP --> AuthAPI : invalid
      AuthAPI --> Frontend : 401 Invalid TOTP code
      Frontend --> User : show error, retry
    }
  }

  opt max attempts exceeded {
    AuthAPI --> Frontend : 429 Too many attempts
    Frontend --> User : lockout, try again later
  }
}
```

```dsl
sequence
participant Browser [browser]
participant API [component]
participant S3 [icon: aws/s3]
participant Processor [icon: aws/lambda]

Browser -> API : GET /upload/presigned-url
API --> Browser : { url, fields }
Browser -> S3 : POST { url, fields, file }
S3 --> Browser : 204 No Content
S3 -> Processor : ObjectCreated event
Processor -> S3 : process file
Processor -> API : update status
Browser -> API : GET /upload/status/:id
alt processing {
  API --> Browser : { status: "processing" }
} else complete {
  API --> Browser : { status: "complete", result }
}
```

```dsl
class
title: Payment Module

interface PaymentProcessor {
  + processPayment(amount: Money) PaymentResult
  + refund(paymentId: String) RefundResult
}

class StripeProcessor {
  + processPayment(amount: Money) PaymentResult
  + refund(paymentId: String) RefundResult
}

class PayPalProcessor {
  + processPayment(amount: Money) PaymentResult
  + refund(paymentId: String) RefundResult
}

class Payment {
  + id: String
  + amount: Money
  + status: PaymentStatus
  + processorId: String
  + createdAt: DateTime
}

class Refund {
  + id: String
  + paymentId: String
  + amount: Money
  + status: RefundStatus
  + createdAt: DateTime
}

class PaymentService {
  - processor: PaymentProcessor
  + processPayment(amount: Money) Payment
  + refund(paymentId: String) Refund
}

PaymentProcessor <|.. StripeProcessor : implements
PaymentProcessor <|.. PayPalProcessor : implements
PaymentService --> PaymentProcessor : uses
PaymentService --> Payment : creates
PaymentService --> Refund : creates
```

```dsl
class
title: Repository Pattern

namespace Domain {
  class User {
    +id: UUID
    +email: String
    +name: String
    +createdAt: DateTime
  }
  class Order {
    +id: UUID
    +userId: UUID
    +items: List<OrderItem>
    +total: Money
    +status: OrderStatus
    +createdAt: DateTime
  }
  enum OrderStatus {
    PENDING
    CONFIRMED
    SHIPPED
    DELIVERED
    CANCELLED
  }
  class OrderItem {
    +productId: UUID
    +quantity: Int
    +price: Money
  }
}

namespace Data {
  interface Repository[T] {
    +findById(id: UUID): T?
    +findAll(): List[T]
    +save(entity: T): T
    +delete(id: UUID): Boolean
    +exists(id: UUID): Boolean
  }

  class UserRepository {
    +findByEmail(email: String): User?
    +findByName(name: String): List[User]
  }
  class OrderRepository {
    +findByUserId(userId: UUID): List[Order]
    +findByStatus(status: OrderStatus): List[Order]
    +findRecentOrders(limit: Int): List[Order]
  }
}

namespace UnitOfWork {
  interface UnitOfWork {
    +userRepository: UserRepository
    +orderRepository: OrderRepository
    +begin(): void
    +commit(): void
    +rollback(): void
  }

  class UnitOfWorkImpl {
    -connection: Connection
    -userRepo: UserRepository
    -orderRepo: OrderRepository
    +begin(): void
    +commit(): void
    +rollback(): void
  }
}

Repository[T] <|-- UserRepository
Repository[T] <|-- OrderRepository
UserRepository ..> User : manages
OrderRepository ..> Order : manages
Order "1" *-- "*" OrderItem : contains
UnitOfWork <|-- UnitOfWorkImpl
UnitOfWorkImpl --> UserRepository : creates
UnitOfWorkImpl --> OrderRepository : creates
```
